SELECT ?name ?point ?ts WHERE {
  ?p a brick:Power .
  ?p rdfs:label ?name ;
     ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts .
  FILTER(regex(?name, "CHWPump01|CondPump02|SupplyFan_AHU01"))
}

SELECT ?point ?ts WHERE {
  ?point ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts .
  FILTER(strcontains(str(?point), "CHWPump01") || strcontains(str(?point), "CondPump02") || strcontains(str(?point), "SupplyFan_AHU01") || strcontains(str(?point), "Supply_Fan_AHU01"))
}

