import csv
ts = {
 "CHWPump01": "81cf18e6-4817-56b7-8c3a-15cf474e449f",
 "CondPump02": "7c6fe42d-3c16-55d2-b72a-7bab085d5a60",
 "SupplyFan_AHU01": "4693f367-6f23-5b26-868f-f17e866f28b6",
}
rows = {}
with open(VALUES_CSV) as f:
    r = csv.reader(f)
    header = next(r)
    for tsid, tstamp, val in r:
        if tsid in ts.values():
            try:
                v = float(val)
            except:
                continue
            rows.setdefault(tsid, []).append((tstamp, v))

for name, tsid in ts.items():
    data = rows.get(tsid, [])
    if not data:
        print(name, "NO DATA"); continue
    full_max = max(v for _,v in data)
    day = [(t,v) for t,v in data if t.startswith("2018-04-24")]
    if not day:
        print(name, "no day data"); continue
    day_max = max(v for _,v in day)
    print(name, "day_max", day_max, "full_max", full_max, "ratio", day_max/full_max)
